import { theme } from "./theme";

export interface CardProps {
  heading: string;
  body: string;
}

export function Card(props: CardProps) {
  return (
    <section style={{ border: theme.border }}>
      <h2>{props.heading}</h2>
      <p>{props.body}</p>
    </section>
  );
}

